cssTemplate:
@page { size: A4 landscape; margin: 0; }
* { box-sizing: border-box; }
html, body { width:297mm; height:210mm; margin:0; padding:0; }
.sc-diploma { --accent:#497b81; --pale:#9dc5c5; width:297mm; height:210mm; position:relative; display:flex; overflow:hidden; background:#faf8f1; color:#142c34; font-family:Arial,Helvetica,sans-serif; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.sc-for-participant { display:none; }
.sc-diploma.rank- .sc-for-winner { display:none; }
.sc-diploma.rank- .sc-for-participant { display:inline; }
.sc-diploma.rank-1 { --accent:#9a7130; --pale:#dfc28a; }
.sc-diploma.rank-2 { --accent:#597182; --pale:#c2d3de; }
.sc-diploma.rank-3 { --accent:#a46447; --pale:#d6a184; }
.sc-main { width:214mm; height:210mm; padding:17mm 17mm 12mm 19mm; position:relative; border-top:2mm solid var(--accent); }
.sc-header { display:flex; justify-content:space-between; align-items:center; }
.sc-brand { font-size:24px; font-weight:800; letter-spacing:-1px; }
.sc-symbol { font-size:19px; font-weight:400; margin-right:5px; color:var(--accent); font-family:monospace; }
.sc-brand-dot { color:var(--accent); }
.sc-edition { text-align:right; font-size:8px; letter-spacing:1.1px; line-height:1.9; font-weight:700; }
.sc-edition span { color:#647779; letter-spacing:.4px; font-weight:400; }
.sc-intro { margin-top:20mm; }
.sc-kicker { font-size:10px; font-weight:700; letter-spacing:2.6px; text-transform:uppercase; color:var(--accent); }
.sc-intro h1 { font-family:Georgia,'Times New Roman',serif; font-size:88px; font-weight:400; letter-spacing:-4px; line-height:1.1; margin:9px 0 4px; }
.sc-heading-dot { color:var(--accent); }
.sc-award { color:var(--accent); font-size:21px; line-height:1.5; letter-spacing:.2px; }
.sc-recipient { margin-top:13mm; }
.sc-small { font-size:8px; letter-spacing:2px; color:#748180; }
.sc-name { margin-top:9px; font-size:31px; font-weight:600; letter-spacing:-.6px; line-height:1.23; overflow-wrap:anywhere; max-width:178mm; }
.sc-name-rule { height:1px; width:100%; background:#d7dace; margin-top:10px; }
.sc-contest { margin:10px 0 0; font-size:15px; line-height:1.4; overflow-wrap:anywhere; max-width:174mm; color:#4d666a; }
.sc-merit { position:absolute; bottom:45mm; left:19mm; font-family:Georgia,'Times New Roman',serif; font-style:italic; font-size:16px; line-height:1.6; color:#647575; }
.sc-footer { position:absolute; bottom:12mm; left:19mm; right:17mm; }
.sc-meta { display:flex; gap:10mm; border-bottom:1px solid #d7dace; padding-bottom:4mm; }
.sc-meta-item { display:flex; flex-direction:column; gap:5px; min-width:26mm; }
.sc-meta-item span { font-size:7px; letter-spacing:1.6px; color:#748180; }
.sc-meta-item strong { font-size:11px; line-height:1.35; font-weight:500; overflow-wrap:anywhere; }
.sc-organizer { max-width:132mm; }
.sc-verification { display:flex; justify-content:space-between; align-items:center; padding-top:3mm; }
.sc-verification-text { display:flex; flex-direction:column; gap:4px; }
.sc-verification-text span { font-family:monospace; font-size:8px; color:#657b7c; }
.sc-verification-text small { font-size:7px; color:#7d8c8b; }
.sc-verification img { width:13mm; height:13mm; mix-blend-mode:multiply; }
.sc-art { position:absolute; top:0; right:0; width:83mm; height:210mm; background:#102c38; color:var(--pale); overflow:hidden; }
.sc-art-top { position:absolute; z-index:2; top:17mm; left:10mm; font-size:12px; font-weight:700; letter-spacing:3px; line-height:1.7; }
.sc-art-top span { font-size:6px; letter-spacing:1.8px; font-weight:400; color:#8aa4ab; }
.sc-numeral { position:absolute; top:20mm; right:4mm; color:var(--pale); opacity:.13; font-family:Georgia,'Times New Roman',serif; font-size:290px; line-height:1; }
.sc-diploma.rank- .sc-numeral { top:35mm; font-size:115px; }
.sc-orbit { position:absolute; width:135mm; height:135mm; border:1px solid #35515b; border-radius:50%; left:-26mm; top:55mm; opacity:.6; }
.sc-orbit-two { width:116mm; height:116mm; left:-16.5mm; top:64.5mm; }
.helix { position:absolute; width:87mm; height:150mm; left:-2mm; bottom:15mm; }
.rank-2 .helix { height:137mm; bottom:18mm; }
.rank-3 .helix { height:122mm; bottom:21mm; }
.sc-medal { display:none; position:absolute; width:61mm; height:84mm; left:11mm; top:80mm; }
.sc-diploma.rank- .helix { display:none; }
.sc-diploma.rank- .sc-medal { display:block; }
.sc-art-bottom { position:absolute; bottom:14mm; left:10mm; font-size:6px; letter-spacing:1.5px; color:#9eb3b8; display:flex; gap:8px; align-items:center; }
.sc-circuit-node { width:5px; height:5px; border:1px solid var(--pale); }
